int[] nums = { 3, 8, 1, 6, 5 };
var evens = nums.Where(x => x % 2 == 0).ToArray();
Console.WriteLine(string.Join(",", evens));
var doubled = nums.Select(x => x * 2).ToArray();
Console.WriteLine(string.Join(",", doubled));
Console.WriteLine(nums.Sum() + " " + nums.Max() + " " + nums.Min());
Console.WriteLine(nums.Count(x => x > 4));
Console.WriteLine(nums.Average());
int[] r = nums.Where(x => x > 2).Select(x => x * 10).OrderBy(x => x).ToArray();
Console.WriteLine(string.Join(",", r));

int[] d = { 2, 2, 3, 3, 3 };
Console.WriteLine(string.Join(",", d.Distinct()));
Console.WriteLine(d.Any(x => x > 2) + " " + d.All(x => x > 2));
var groups = d.GroupBy(x => x);
foreach (var g in groups) Console.WriteLine(g.Key + ":" + g.Count());
